    private static Element locateParagraph(Document d,String locator){if(locator==null||!locator.matches("body/p:[1-9][0-9]*"))throw new IllegalArgumentException("unsafe paragraph locator: "+locator);int n=Integer.parseInt(locator.substring("body/p:".length()));List<Element>ps=bodyParagraphs(d);if(n>ps.size())throw new IllegalArgumentException("paragraph locator out of range");return ps.get(n-1);}
