    private static Element locateStandaloneShape(Document d,String locator){if(locator==null||!locator.matches("body/p:[1-9][0-9]*/drawing-shape:[1-9][0-9]*"))throw new IllegalArgumentException("unsafe shape locator: "+locator);String[] chunks=locator.split("/");Element p=locateParagraph(d,chunks[0]+"/"+chunks[1]);int target=Integer.parseInt(chunks[2].substring("drawing-shape:".length()));NodeList ns=p.getElementsByTagNameNS(WPS,"wsp");int n=0;for(int i=0;i<ns.getLength();i++){Element e=(Element)ns.item(i);if(hasAncestor(e,WPG,"wgp"))continue;if(++n==target)return e;}throw new IllegalArgumentException("shape locator out of range");}
